program = '''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            comp = set()
            while q:
                y, x = q.popleft()
                comp.add((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            r0, r1 = min(y for y,x in comp), max(y for y,x in comp)
            c0, c1 = min(x for y,x in comp), max(x for y,x in comp)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            perimeter = {(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)
                         if y in (r0,r1) or x in (c0,c1)}
            if comp == perimeter and all(grid[y][x] == bg for y in range(r0+1,r1) for x in range(c0+1,c1)):
                fill = 2 if (r1-r0+1) % 2 == 0 else 7
                for y in range(r0+1,r1):
                    for x in range(c0+1,c1):
                        out[y][x] = fill
    return out
'''
